  $freezePath=Join-Path $temp 'freeze.json';Write-EnvelopeJson $freezePath $freeze;foreach($damage in @([pscustomobject]@{name='duplicate-repo';mutate={param($d)$d.final_repositories+=([ordered]@{repo_id='project-shell';commit=$sourceCommit;tree=('0'*40)})}},[pscustomobject]@{name='substituted-commit';mutate={param($d)$d.final_repositories[0].commit=('0'*40)}},[pscustomobject]@{name='outside-path';mutate={param($d)$d.changed_paths[0].paths=@('outside/')}})){$damaged=Copy-Envelope $freeze;&$damage.mutate $damaged;$damagedPath=Join-Path $temp ("freeze-$($damage.name).json");Write-EnvelopeJson $damagedPath $damaged;$rejected=$false;try{Invoke-MorphospaceFreezeCandidate -WorkspaceRoot $ws -UnitId u002 -CandidateFreeze $damagedPath -OutPath (Join-Path $ws 'receipts\damaged-freeze.json')|Out-Null}catch{$rejected=$true};Assert-Envelope $rejected "FreezeCandidate accepted $($damage.name) damage"};[IO.File]::WriteAllText((Join-Path $sourceRepo 'morphospace\dirty.txt'),'dirty',[Text.UTF8Encoding]::new($false));$dirtyRejected=$false;try{Invoke-MorphospaceFreezeCandidate -WorkspaceRoot $ws -UnitId u002 -CandidateFreeze $freezePath -OutPath (Join-Path $ws 'receipts\dirty-freeze.json')|Out-Null}catch{$dirtyRejected=$true};Remove-Item -LiteralPath (Join-Path $sourceRepo 'morphospace\dirty.txt') -Force;Assert-Envelope $dirtyRejected 'FreezeCandidate accepted a dirty clean-only repository';$freezeOut=Join-Path $ws 'receipts\u002-freeze.json';$freezeDry=Invoke-MorphospaceFreezeCandidate -WorkspaceRoot $ws -UnitId u002 -CandidateFreeze $freezePath -OutPath $freezeOut -Timestamp '2026-08-25T00:03:00.0000000Z';$freezeRun=Invoke-MorphospaceFreezeCandidate -WorkspaceRoot $ws -UnitId u002 -CandidateFreeze $freezePath -ExpectedCandidateFreezeSha256 $freezeDry.audit_receipt.sha256 -OutPath $freezeOut -Timestamp '2026-08-25T00:03:00.0000000Z' -Execute;Assert-Envelope ($freezeRun.transition -eq 'candidate-frozen') 'candidate freeze did not bind immutable closure';$frozen=Read-MorphospaceProtoc